const data = $input.first().json;

const candidateId   = data.candidateId;
const firstName     = data.firstName || 'Candidat';
const lastName      = data.lastName  || '';
const jobTitle      = data.jobOfferTitle || 'le poste';
const status        = data.status || 'CV_REVIEWED';
const cvUrl         = data.cvUrl  || null;
const email         = data.email  || '';
const hrName        = data.updatedBy || 'RH';
const managerEmail  = data.managerEmail || null;

// Mapping statut → label lisible
const statusLabels = {
  CV_REVIEWED:       '✅ CV validé — en attente d\'analyse Manager',
  PHONE_SCREENING:   '📞 Pré-qualification téléphonique',
  TECHNICAL_TEST:    '💻 Test technique à planifier',
  INTERVIEW:         '🎤 Entretien à planifier',
  FINAL_INTERVIEW:   '🏆 Entretien final',
  ACCEPTED:          '🎉 Candidat accepté',
  REJECTED:          '❌ Candidat refusé'
};
const statusLabel = statusLabels[status] || status;
const profileUrl = `http://localhost:4200/admin/candidates`;

return [{ json: {
  candidateId, firstName, lastName, email, jobTitle,
  status, statusLabel, cvUrl, hrName, managerEmail, profileUrl,
  validatedAt: new Date().toISOString()
} }];

const data = $input.first().json;

const candidateId = data.candidateId;
const firstName   = data.candidateFirstName || 'Candidat';
const lastName     = data.candidateLastName  || '';
const email        = data.candidateEmail     || '';
const jobTitle     = data.jobOfferTitle || 'le poste';
const status       = data.status || '';

const accepted = status === 'ACCEPTED' || status === 'HIRED';

const subject = accepted
  ? `🎉 Félicitations — votre candidature pour ${jobTitle}`
  : `Réponse à votre candidature — ${jobTitle}`;

const htmlBody = accepted
  ? `<html><body style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
  <div style="background: #059669; color: white; padding: 24px; border-radius: 8px 8px 0 0;">
    <h1 style="margin:0">JOB4YOU</h1>
    <p style="margin:4px 0 0">Votre candidature a été retenue</p>
  </div>
  <div style="background: #f8fafc; padding: 24px; border-radius: 0 0 8px 8px;">
    <h2 style="color: #059669;">Félicitations ${firstName} ${lastName} !</h2>
    <p>Nous avons le plaisir de vous informer que votre candidature pour le poste de <strong>${jobTitle}</strong> a été retenue.</p>
    <p>Notre équipe RH vous contactera prochainement pour vous communiquer les prochaines étapes.</p>
    <p style="color: #6b7280; font-size: 12px; margin-top: 24px;">Cet email a été envoyé automatiquement par JOB4YOU Agent 3.</p>
  </div>
</body></html>`
  : `<html><body style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
  <div style="background: #64748b; color: white; padding: 24px; border-radius: 8px 8px 0 0;">
    <h1 style="margin:0">JOB4YOU</h1>
    <p style="margin:4px 0 0">Réponse à votre candidature</p>
  </div>
  <div style="background: #f8fafc; padding: 24px; border-radius: 0 0 8px 8px;">
    <h2 style="color: #374151;">Bonjour ${firstName} ${lastName},</h2>
    <p>Nous vous remercions pour l'intérêt porté au poste de <strong>${jobTitle}</strong> et pour le temps consacré à votre candidature.</p>
    <p>Après étude attentive de votre dossier, nous ne donnerons malheureusement pas suite à votre candidature pour ce poste.</p>
    <p>Nous vous encourageons à consulter nos autres offres et vous souhaitons plein succès dans vos recherches.</p>
    <p style="color: #6b7280; font-size: 12px; margin-top: 24px;">Cet email a été envoyé automatiquement par JOB4YOU Agent 3.</p>
  </div>
</body></html>`;

return [{ json: {
  candidateId, firstName, lastName, email, jobTitle, status, accepted, subject, htmlBody,
  decidedAt: new Date().toISOString()
} }];
